/* A 4-bit grayscale pixelmap, neither compressed nor transparent, drawn with
   its left edge clipped by 0 to 9 of its 10 columns, the clip starting on an
   even and on an odd canvas column. Every visible pixel must be the image's
   pixel at that position, and nothing outside the clipped image may change.

   The image's pixels are never 0 and the canvas is cleared to 0, so a pixel
   read from the wrong place in the image, or from past its end, or written
   outside the clip, shows. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_4bpp_pixelmap_clip_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#define TEST_WIDTH          64
#define TEST_HEIGHT         16
#define TEST_IMAGE_WIDTH    10
#define TEST_IMAGE_HEIGHT   4
#define TEST_IMAGE_STRIDE   ((TEST_IMAGE_WIDTH + 1) >> 1)
#define TEST_IMAGE_TOP      2

UINT gx_validation_graphics_driver_setup_4bpp_grayscale(GX_DISPLAY *display);

static UINT           failed_tests = 0;

static TX_THREAD      test_thread;
static ULONG          test_thread_stack[4096 / sizeof(ULONG)];

static GX_DISPLAY     test_display;
static GX_CANVAS      test_canvas;
static GX_WINDOW_ROOT test_root;
static GX_UBYTE       test_canvas_memory[TEST_WIDTH * TEST_HEIGHT / 2];
static GX_UBYTE       test_image_data[TEST_IMAGE_STRIDE * TEST_IMAGE_HEIGHT];
static GX_PIXELMAP    test_image;

/* Pixel x of row y in 4 bpp memory, high nibble first.  */
static GX_UBYTE test_get(GX_UBYTE *memory, INT stride, INT x, INT y)
{
GX_UBYTE byte = memory[y * stride + (x >> 1)];

    return (GX_UBYTE)((x & 1) ? (byte & 0x0f) : (byte >> 4));
}

static VOID test_clip(INT left, INT clip)
{
GX_RECTANGLE dirty;
GX_UBYTE     expected;
GX_UBYTE     actual;
INT          x;
INT          y;

    memset(test_canvas_memory, 0, sizeof(test_canvas_memory));

    /* The dirty area starts at left; the image starts clip columns before.  */
    gx_utility_rectangle_define(&dirty, (GX_VALUE)left, 0, TEST_WIDTH - 1, TEST_HEIGHT - 1);
    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_initiate(&test_canvas, (GX_WIDGET *)&test_root, &dirty));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_pixelmap_draw((GX_VALUE)(left - clip), TEST_IMAGE_TOP, &test_image));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_drawing_complete(&test_canvas, GX_FALSE));

    for (y = 0; y < TEST_HEIGHT; y++)
    {
        for (x = 0; x < TEST_WIDTH; x++)
        {
            expected = 0;
            if (y >= TEST_IMAGE_TOP && y < TEST_IMAGE_TOP + TEST_IMAGE_HEIGHT &&
                x >= left && x < left - clip + TEST_IMAGE_WIDTH)
            {
                expected = test_get(test_image_data, TEST_IMAGE_STRIDE, x - (left - clip), y - TEST_IMAGE_TOP);
            }
            actual = test_get(test_canvas_memory, TEST_WIDTH / 2, x, y);
            if (actual != expected)
            {
                printf("clipped by %d at column %d: pixel (%d,%d) is 0x%x, expected 0x%x\n",
                       clip, left, x, y, actual, expected);
                failed_tests++;
                return;
            }
        }
    }
}

static VOID test_thread_entry(ULONG id)
{
GX_RECTANGLE size;
INT          index;
INT          clip;

    /* Pixel values 1 to 15, never 0.  */
    for (index = 0; index < (INT)sizeof(test_image_data); index++)
    {
        test_image_data[index] = (GX_UBYTE)((((index * 2) % 15 + 1) << 4) | ((index * 2 + 1) % 15 + 1));
    }
    memset(&test_image, 0, sizeof(GX_PIXELMAP));
    test_image.gx_pixelmap_format = GX_COLOR_FORMAT_4BIT_GRAY;
    test_image.gx_pixelmap_data = test_image_data;
    test_image.gx_pixelmap_data_size = sizeof(test_image_data);
    test_image.gx_pixelmap_width = TEST_IMAGE_WIDTH;
    test_image.gx_pixelmap_height = TEST_IMAGE_HEIGHT;

    gx_system_initialize();

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_display, "test_display",
                                            gx_validation_graphics_driver_setup_4bpp_grayscale,
                                            TEST_WIDTH, TEST_HEIGHT));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_canvas, "test_canvas", &test_display, GX_CANVAS_SIMPLE,
                                           TEST_WIDTH, TEST_HEIGHT, (GX_COLOR *)test_canvas_memory,
                                           sizeof(test_canvas_memory)));
    gx_utility_rectangle_define(&size, 0, 0, TEST_WIDTH - 1, TEST_HEIGHT - 1);
    EXPECT_EQ(GX_SUCCESS, gx_window_root_create(&test_root, "test_root", &test_canvas, GX_STYLE_BORDER_NONE,
                                                GX_NULL, &size));

    for (clip = 0; clip < TEST_IMAGE_WIDTH; clip++)
    {
        test_clip(20, clip);
        test_clip(21, clip);
    }

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

